    if (key === 'ArrowLeft' || key === 'ArrowRight') {
      this.flowPause = 1.5;
      this.set(this.time + (key === 'ArrowRight' ? 0.04 : -0.04));
      return true;
    }
    if (key === 'Home') {
      this.flowPause = 1.5;
      this.set(0);
      return true;
    }
    if (key === 'End') {
      this.flowPause = 1.5;
      this.set(0.75);
      return true;
    }
    return false;
