    const day = smooth01(0.07, 0.5, sunAlt);
    const night = 1 - smooth01(-0.36, 0.08, sunAlt);
    const golden = Math.max(0, 1 - Math.abs(sunAlt) / 0.24);
    const sunA = smooth01(-0.08, 0.1, sunAlt);
    const moonA = smooth01(-0.1, 0.06, moonAlt);

